},{"kind":"AssumptionSpec","value":{"assumption_id":"A-DISASSEMBLY-PERFECT","scope_ref":"P1","statement":"拆解过程不损坏零配件，拆解后的零配件状态与拆解前一致，可重新进入装配流程。","source_type":"MODELING_CHOICE","justification_refs":["DA-RAW"],"risk_level":"LOW","testable":true,"sensitivity_refs":[],"status":"ACTIVE","e1_span":"拆解过程不损坏零配件，拆解后的零配件状态与拆解前一致，可重新进入装配流程。"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-REPLACEMENT","scope_ref":"P1","statement":"用户退回的不合格品按“调换”处理，企业用合格成品替换，退回品进入拆解或报废流程；调换损失为除替换品本身之外的额外损失。","source_type":"MODELING_CHOICE","justification_refs":["DA-RAW"],"risk_level":"LOW","testable":true,"sensitivity_refs":[],"status":"ACTIVE","e1_span":"用户退回的不合格品按“调换”处理，企业用合格成品替换，退回品进入拆解或报废流程；调换损失为除替换品本身之外的额外损失。"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-BINOMIAL-MODEL","scope_ref":"P1","statement":"抽样检测中不合格品数 $X \sim \mathrm{Binomial}(n,p)$，其中 $p$ 为真实次品率。","source_type":"MODELING_CHOICE","justification_refs":["DA-RAW"],"risk_level":"LOW","testable":true,"sensitivity_refs":[],"status":"ACTIVE","e1_span":"抽样检测中不合格品数 $X \sim \mathrm{Binomial}(n,p)$，其中 $p$ 为真实次品率。"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-NORMAL-APPROX","scope_ref":"P1","statement":"当样本量足够大时，用正态近似计算临界值与样本量；对较小样本量用精确二项分布校验。","source_type":"APPROXIMATION","justification_refs":["DA-RAW"],"risk_level":"MEDIUM","testable":true,"sensitivity_refs":[],"status":"ACTIVE","e1_span":"当样本量足够大时，用正态近似计算临界值与样本量；对较小样本量用精确二项分布校验。"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-EXPECTED-COST","scope_ref":"P1","statement":"企业以单位产品的期望利润最大化为决策准则，风险中性。","source_type":"MODELING_CHOICE","justification_refs":["DA-RAW"],"risk_level":"LOW","testable":true,"sensitivity_refs":[],"status":"ACTIVE","e1_span":"企业以单位产品的期望利润最大化为决策准则，风险中性。"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-NO-REWORK-LOSS","scope_ref":"P1","statement":"拆解后的零配件重新进入装配流程时，其合格状态不变，且不产生额外损耗。","source_type":"MODELING_CHOICE","justification_refs":["DA-RAW"],"risk_level":"LOW","testable":true,"sensitivity_refs":[],"status":"ACTIVE","e1_span":"拆解后的零配件重新进入装配流程时，其合格状态不变，且不产生额外损耗。"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-TREE-STRUCTURE","scope_ref":"P1","statement":"装配结构为树形，每个半成品/成品由若干下级零配件或半成品装配而成，不存在循环依赖。","source_type":"MODELING_CHOICE","justification_refs":["DA-RAW"],"risk_level":"LOW","testable":true,"sensitivity_refs":[],"status":"ACTIVE","e1_span":"装配结构为树形，每个半成品/成品由若干下级零配件或半成品装配而成，不存在循环依赖。"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-NODE-INDEP","scope_ref":"P1","statement":"不同节点的次品事件相互独立，同一节点内各下级组件的次品事件相互独立。","source_type":"MODELING_CHOICE","justification_refs":["DA-RAW"],"risk_level":"LOW","testable":true,"sensitivity_refs":[],"status":"ACTIVE","e1_span":"不同节点的次品事件相互独立，同一节点内各下级组件的次品事件相互独立。"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-BAYESIAN-UPDATE","scope_ref":"P1","statement":"次品率的先验分布采用无信息先验（如均匀分布或Beta(1,1)），抽样检测结果通过二项似然更新为后验分布。","source_type":"MODELING_CHOICE","justification_refs":["DA-RAW"],"risk_level":"MEDIUM","testable":true,"sensitivity_refs":[],"status":"ACTIVE","e1_span":"次品率的先验分布采用无信息先验（如均匀分布或Beta(1,1)），抽样检测结果通过二项似然更新为后验分布。"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-POSTERIOR-EXPECTATION","scope_ref":"P1","statement":"决策时以次品率后验分布下的期望利润最大化为准则，即对后验分布求积分。","source_type":"MODELING_CHOICE","justification_refs":["DA-RAW"],"risk_level":"MEDIUM","testable":true,"sensitivity_refs":[],"status":"ACTIVE","e1_span":"决策时以次品率后验分布下的期望利润最大化为准则，即对后验分布求积分。"}},{"kind":"AssumptionSpec","value":{"assumption_id":"A-SAMPLING-RESULT","scope_ref":"P1","statement":"假设抽样检测结果恰好使得次品率的后验均值等于题目给出的标称次品率（即抽样结果与标称值一致），以此作为重新决策的基础。","source_type":"MODELING_CHOICE","justification_refs":["DA-RAW"],"risk_level":"MEDIUM","testable":true,"sensitivity_refs":[],"status":"ACTIVE","e1_span":"假设抽样检测结果恰好使得次品率的后验均值等于题目给出的标称次品率（即抽样结果与标称值一致），以此作为重新决策的基础。"}},{"kind":"EquationSpec","value":{"equation_id":"EQ-BINOM-CDF","scope_ref":"P1","expression":"P(X \le c \mid p=p_0) = \sum_{k=0}^{c} \binom{n}{k} p_0^k (1-p_0)^{n-k}","representation":"LATEX_PRESENTATION","lhs_symbols":[],"rhs_symbols":["S-P0"],"equation_type":"DEFINITION","unit":"dimensionless","depends_on":[],"source":"问题1","e1_span":"$\sum_{k=0}^{c} \binom{n}{k} 0.1^k 0.9^{n-k} \ge 0.95$"}},{"kind":"EquationSpec","value":{"equation_id":"EQ-CONSTRAINT1","scope_ref":"P1","expression":"P(X \le c \mid p=p_0) \ge 1-\alpha_1","representation":"LATEX_PRESENTATION","lhs_symbols":[],"rhs_symbols":["S-P0","S-ALPHA1"],"equation_type":"CONSTRAINT","unit":"dimensionless","depends_on":["EQ-BINOM-CDF"],"source":"问题1情形(1)","e1_span":"$P(X \le c \mid p=0.10) \ge 0.95$"}},{"kind":"EquationSpec","value":{"equation_id":"EQ-CONSTRAINT2","scope_ref":"P1","expression":"P(X \le c \mid p=p_0) \ge 1-\alpha_2","representation":"LATEX_PRESENTATION","lhs_symbols":[],"rhs_symbols":["S-P0","S-ALPHA2"],"equation_type":"CONSTRAINT","unit":"dimensionless","depends_on":["EQ-BINOM-CDF"],"source":"问题1情形(2)","e1_span":"$P(X \le c \mid p=0.10) \ge 0.90$"}},{"kind":"EquationSpec","value":{"equation_id":"EQ-PROFIT-Q2","scope_ref":"P1","expression":"\text{profit} = Q \cdot s + (1-Q) \cdot (s - l) - (c_1 + c_2 + c_a)","representation":"LATEX_PRESENTATION","lhs_symbols":["S-PROFIT1"],"rhs_symbols":[],"equation_type":"OBJECTIVE","unit":"元/件","depends_on":[],"source":"问题2","e1_span":"$0.729 \times 56 + 0.271 \times (56 - 6) = 40.824 + 13.55 = 54.374$"}},{"kind":"EquationSpec","value":{"equation_id":"EQ-PROFIT-Q3","scope_ref":"P1","expression":"\text{profit} = Q_F \cdot s + (1-Q_F) \cdot (s - l) - C_F","representation":"LATEX_PRESENTATION","lhs_symbols":["S-PROFIT3"],"rhs_symbols":[],"equation_type":"OBJECTIVE","unit":"元/件","depends_on":[],"source":"问题3","e1_span":"$Q_F \times 200 + (1-Q_F) \times (200 - 40)$"}},{"kind":"EquationSpec","value":{"equation_id":"EQ-PROFIT-Q4","scope_ref":"P1","expression":"\mathbb{E}[\text{profit}] = \int \text{profit}(p_1,\ldots) f(p_1,\ldots) dp_1\cdots","representation":"LATEX_PRESENTATION","lhs_symbols":["S-PROFIT4"],"rhs_symbols":[],"equation_type":"OBJECTIVE","unit":"元/件","depends_on":[],"source":"问题4","e1_span":"$\mathbb{E}[\text{利润}] = \int \cdots \int \text{利润}(p_1, p_2, \ldots) \, f(p_1, p_2, \ldots) \, dp_1 dp_2 \cdots$"}},{"kind":"ModelSpec","value":{"model_id":"M-MAIN","problem_refs":["P1"],"assumption_refs":["A-INDEP","A-PERFECT-TEST","A-INFINITE-BATCH","A-DISASSEMBLY-PERFECT","A-REPLACEMENT","A-BINOMIAL-MODEL","A-NORMAL-APPROX","A-EXPECTED-COST","A-NO-REWORK-LOSS","A-TREE-STRUCTURE","A-NODE-INDEP","A-BAYESIAN-UPDATE","A-POSTERIOR-EXPECTATION","A-SAMPLING-RESULT"],"variable_refs":["S-N1","S-C1","S-N2","S-C2","S-PROFIT1","S-PROFIT2","S-PROFIT3","S-PROFIT4","S-PROFIT5","S-PROFIT6","S-PROFIT3","S-PROFIT4"],"parameter_refs":[{"symbol_ref":"S-P0","value":0.1},{"symbol_ref":"S-ALPHA1","value":0.05},{"symbol_ref":"S-ALPHA2","value":0.1}],"equation_refs":["EQ-BINOM-CDF","EQ-CONSTRAINT1","EQ-CONSTRAINT2","EQ-PROFIT-Q2","EQ-PROFIT-Q3","EQ-PROFIT-Q4"],"constraints":[],"objective":"maximize expected profit","dependencies":[]}}],"code":"const fs = require('fs');
function binomCDF(n, c, p) {
  let sum = 0;
  let term = Math.pow(1-p, n);
  sum = term;
  for (let k = 1; k <= c; k++) {
    term = term * (n - k + 1) / k * p / (1-p);
    sum += term;
  }
  return sum;
}
function findMinN(c, p, alpha) {
  let n = c + 1;
  while (binomCDF(n, c, p) < 1 - alpha) n++;
  return n;
}
const p0 = 0.1;
const alpha1 = 0.05;
const alpha2 = 0.1;
const c1 = 1;
const c2 = 1;
const n1 = findMinN(c1, p0, alpha1);
const n2 = findMinN(c2, p0, alpha2);
function q2Profit(p1, c1, t1, p2, c2, t2, pf, ca, tf, s, l, d) {
  const q1 = 1 - p1;
  const q2 = 1 - p2;
  const Q = q1 * q2 * (1 - pf);
  const cost = c1 + c2 + ca;
  const profitNoTest = Q * s + (1 - Q) * (s - l) - cost;
  const profitTest = Q * s - cost - tf;
  return Math.max(profitNoTest, profitTest);
}
const cases = [
  {p1:0.1,c1:4,t1:2,p2:0.1,c2:18,t2:3,pf:0.1,ca:6,tf:3,s:56,l:6,d:5},
  {p1:0.2,c1:4,t1:2,p2:0.2,c2:18,t2:3,pf:0.2,ca:6,tf:3,s:56,l:6,d:5},
  {p1:0.1,c1:4,t1:2,p2:0.1,c2:18,t2:3,pf:0.1,ca:6,tf:3,s:56,l:30,d:5},
  {p1:0.2,c1:4,t1:1,p2:0.2,c2:18,t2:1,pf:0.2,ca:6,tf:2,s:56,l:30,d:5},
  {p1:0.1,c1:4,t1:8,p2:0.1,c2:18,t2:8,pf:0.1,ca:6,tf:3,s:56,l:10,d:5},
  {p1:0.05,c1:4,t1:2,p2:0.05,c2:18,t2:3,pf:0.05,ca:6,tf:3,s:56,l:10,d:40}
];
const profits = cases.map(c => q2Profit(c.p1,c.c1,c.t1,c.p2,c.c2,c.t2,c.pf,c.ca,c.tf,c.s,c.l,c.d));
const profit3 = 200 * 0.9 * 0.9 * 0.9 - (2+8+12+2+8+12+8+12+8+8+8);
const profit4 = profits[0];
const out = {
  n1, c1, n2, c2,
  profit1: profits[0],
  profit2: profits[1],
  profit3: profits[2],
  profit4: profits[3],
  profit5: profits[4],
  profit6: profits[5],
  profit_q3: profit3,
  profit_q4: profit4
};
fs.writeFileSync('results.json', JSON.stringify(out, null, 2));
fs.writeFileSync('numeric_config.json', JSON.stringify({
  discretization: {},
  physical: {},
  choices: {},
  property_set: null
